/**
 * Copy the kuromoji dictionary out of node_modules into static/ so yomu serves
 * it itself.
 *
 * The upstream README points at a jsdelivr CDN. That is rejected deliberately:
 * everything else in this homelab is served from behind its own Caddy, and a CDN
 * dependency would make the reader stop working the moment the network does --
 * for a tool whose entire job is offline dictionary lookup while reading.
 *
 * ~18MB of .dat.gz, so it is gitignored and regenerated by `yarn prepare`
 * rather than committed.
 */
import { cpSync, existsSync, mkdirSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const src = join(root, 'node_modules', '@patdx', 'kuromoji', 'dict');
const dest = join(root, 'static', 'dict');

if (!existsSync(src)) {
	console.error(`kuromoji dictionary not found at ${src} -- run an install first`);
	process.exit(1);
}

mkdirSync(dest, { recursive: true });
cpSync(src, dest, { recursive: true });

console.log(`dictionary synced: ${readdirSync(dest).length} files -> static/dict`);
